export function shouldFlagNeedsReview(parseConfidence: number | null | undefined, warnings: unknown): boolean {
  const confidence = Number(parseConfidence ?? 0);
  const warningCount = Array.isArray(warnings) ? warnings.length : 0;

  return confidence < 0.7 || warningCount >= 3;
}

type RefreshOptions = {
  forceRefresh: boolean;
  hasExclusivityOverride: boolean;
  exclusivityOverride?: string | null;
  imageBlocked: boolean;
  resolvedRefreshEstimatedValue: number | null;
  forcedFields?: CatalogRow | null;
};

function hasForcedRefreshField(options: RefreshOptions, field: string): boolean {
  return Boolean(options.forcedFields && Object.prototype.hasOwnProperty.call(options.forcedFields, field));
}

function nullableFiniteNumber(value: unknown): number | null {
  if (value == null || value === "") return null;
  const number = Number(value);
  return Number.isFinite(number) ? number : null;
}

export function resolveLookupEstimatedValues(
  existingCatalogValue: unknown,
  parsedCatalogValue: unknown,
  requestedVariantValue: unknown,
): { catalogEstimatedValue: number | null; lookupEstimatedValue: number | null } {
  const existingValue = nullableFiniteNumber(existingCatalogValue);
  const parsedValue = nullableFiniteNumber(parsedCatalogValue);
  const variantValue = nullableFiniteNumber(requestedVariantValue);
  const catalogEstimatedValue = variantValue != null ? (existingValue ?? parsedValue) : (parsedValue ?? existingValue);

  return {
    catalogEstimatedValue,
    lookupEstimatedValue: variantValue ?? catalogEstimatedValue,
  };
}

function normalizeSetName(value: unknown): string {
  return String(value ?? "").replace(/\s+/g, " ").trim();
}

export function getSetTotalOverride(setName: unknown): number | null {
  const normalized = normalizeSetName(setName);
  return SET_TOTAL_OVERRIDES[normalized] ?? null;
}

export function shouldPromoteSpecificSet(existingSetName: unknown, parsedSetName: unknown): boolean {
  const existing = normalizeSetName(existingSetName);
  const parsed = normalizeSetName(parsedSetName);

  if (!parsed) return false;
  if (!existing) return true;
  return GENERIC_SET_NAMES.has(existing) && parsed !== existing;
}

export function mergeNeedsReview(existingNeedsReview: unknown, parsedNeedsReview: unknown): boolean {
  return Boolean(existingNeedsReview || parsedNeedsReview);
}

const TRUSTED_OVERRIDE_FIELDS = [
  "pop_name",
  "character",
  "franchise",
  "set_name",
  "number",
  "variant",
  "exclusivity",
  "pop_type",
  "pop_style",
  "description",
  "display_description",
  "description_source",
  "description_source_url",
  "description_quality",
  "description_last_checked",
  "description_review_notes",
  "vault_status",
  "release_date",
  "limited_edition",
  "limited_count",
  "edition_notes",
] as const;

export function buildTrustedOverrideUpdate(
  overrideFields: CatalogRow | null | undefined,
  parsed: CatalogRow,
): CatalogRow {
  if (!overrideFields) return {};

  const updates: CatalogRow = {};
  for (const field of TRUSTED_OVERRIDE_FIELDS) {
    if (Object.prototype.hasOwnProperty.call(overrideFields, field)) {
      updates[field] = parsed[field] ?? null;
    }
  }

  updates.parse_reason_codes = [];
  updates.needs_review = Boolean(overrideFields.needs_review ?? false);
  if (parsed.parse_confidence != null) {
    updates.parse_confidence = parsed.parse_confidence;
  }

  return updates;
}

export type ExplicitProductClassification = {
  pop_type: string;
  pop_style: string;
};

export function getExplicitProductClassification(sourceText: unknown): ExplicitProductClassification | null {
  const text = String(sourceText ?? "").replace(/\s+/g, " ").trim();
  if (/\bbitty\s+pop!?\s+arcade\b/i.test(text)) {
    return { pop_type: "Bitty Pop! Arcade", pop_style: "Bitty Pop Arcade" };
  }
  if (/\b(?:pop!?\s+)?mug\b/i.test(text)) {
    return { pop_type: "Pop! Mug", pop_style: "Mug" };
  }
  if (/\bpop!?\s+premium\b|\bpremium\s+pop!?\b/i.test(text)) {
    return { pop_type: "Pop! Premium", pop_style: "Premium" };
  }
  if (/\bpop!?\s+rides?\b/i.test(text)) {
    return { pop_type: "Pop! Rides", pop_style: "Ride" };
  }
  if (/\bpop!?\s+town\b/i.test(text)) {
    return { pop_type: "Pop! Town", pop_style: "Town" };
  }
  if (/\bpop!?\s+deluxe\b|\bdeluxe\s+pop!?\b/i.test(text)) {
    return { pop_type: "Pop! Deluxe", pop_style: "Deluxe" };
  }
  if (/\bpop!?\s+super\b|\bsuper\s+pop!?\b/i.test(text)) {
    return { pop_type: "Pop! Super", pop_style: "Super" };
  }
  if (/\bpop!?\s+disney\b/i.test(text) && (/\bjumbo\b/i.test(text) || /\b(?:10|ten)[ -]?(?:inch|in\.?|")\b/i.test(text))) {
    return { pop_type: "Pop! Disney", pop_style: "Jumbo" };
  }
  if (/\bpop!?\s+games\b/i.test(text) && (/\bjumbo\b/i.test(text) || /\b(?:10|ten)[ -]?(?:inch|in\.?|")\b/i.test(text))) {
    return { pop_type: "Pop! Games", pop_style: "Jumbo" };
  }
  if (
    /\b(?:marvel|avengers|hulkbuster)\b/i.test(text) &&
    (/\bsuper[- ]?sized\b/i.test(text) || /\b(?:6|six)[ -]?(?:inch|in\.?|")\b/i.test(text))
  ) {
    return { pop_type: "Pop! Marvel", pop_style: "Jumbo" };
  }
  if (/\bpop!?\s+(?:movie\s+)?moments?\b/i.test(text)) {
    return { pop_type: "Pop! Moments", pop_style: "Moment" };
  }
  return null;
}

const OPTIONAL_NUMBER_STYLES = new Set([
  "2-Pack",
  "3-Pack",
  "4-Pack",
  "5-Pack",
  "Bitty Pop",
  "Bitty Pop Arcade",
  "Deluxe",
  "Moment",
  "Movie Moment",
  "Movie Moments",
  "Mug",
]);

export function shouldWarnMissingNumber(number: unknown, popStyle: unknown): boolean {
  return !String(number ?? "").trim() && !OPTIONAL_NUMBER_STYLES.has(String(popStyle ?? "").trim());
}

export function normalizeMultipackNumber(
  number: string | null,
  popStyle: unknown,
  sourceText: unknown,
): string | null {
  const style = String(popStyle ?? "").trim();
  const text = String(sourceText ?? "").replace(/\s+/g, " ").trim();
  const isMultipack = /^\d+-Pack$/i.test(style);
  const sourceSaysMultipack = /\b(?:two|three|four|five|\d+)[ -]?pack\b/i.test(text);
  const hasExplicitBoxNumber = /(?:#|\bno\.?\s*)\d{1,5}\b/i.test(text);

  if (isMultipack && sourceSaysMultipack && !hasExplicitBoxNumber) return null;
  return number;
}

function normalizedCollisionPart(value: unknown): string {
  return String(value ?? "")
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, " ")
    .replace(/\s+/g, " ")
    .trim();
}

export function buildCatalogCollisionKey(item: CatalogRow): string | null {
  const setName = normalizedCollisionPart(item.set_name);
  const number = normalizedCollisionPart(item.number);
  const popType = normalizedCollisionPart(item.pop_type);
  const popStyle = normalizedCollisionPart(item.pop_style || "Standard");

  if (!setName || !number) return null;
  return `${setName}:${number}:${popType}:${popStyle}`;
}

