function normalizedSetLabelKey(value: unknown): string {
  return String(value ?? "")
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, " ")
    .replace(/\s+/g, " ")
    .trim();
}

export function canonicalizeSetLabel(value: unknown): string | null {
  const original = String(value ?? "").replace(/\s+/g, " ").trim();
  if (!original) return null;
  return CANONICAL_SET_LABELS[normalizedSetLabelKey(original)] ?? original;
}

const CANONICAL_FRANCHISE_LABELS: Record<string, string> = {
  "pokemon": "Pokémon",
  "pok mon": "Pokémon",
};

export function canonicalizeFranchiseLabel(value: unknown): string | null {
  const original = String(value ?? "").replace(/\s+/g, " ").trim();
  if (!original) return null;
  return CANONICAL_FRANCHISE_LABELS[normalizedSetLabelKey(original)] ?? original;
}

export function pruneResolvedParseReasonCodes(reasonCodes: unknown, row: CatalogRow): string[] {
  const codes = Array.isArray(reasonCodes) ? reasonCodes.map((code) => String(code)) : [];
  return codes.filter((code) => {
    if (code === "missing_number" && row.number) return false;
    if (code === "missing_franchise" && row.franchise) return false;
    if (code === "missing_character" && row.character) return false;
    if (code === "missing_set" && row.set_name) return false;
    if (code === "estimated_value_missing" && Number(row.estimated_value ?? 0) > 0) return false;
    return true;
  });
}

export function buildCatalogRefreshUpdate(
  existing: CatalogRow,
  newPop: CatalogRow,
  options: RefreshOptions,
): CatalogRow {
  const variant = hasForcedRefreshField(options, "variant")
    ? (newPop.variant ?? null)
    : (newPop.variant || existing.variant);
  const exclusivity = options.hasExclusivityOverride
    ? options.exclusivityOverride
    : hasForcedRefreshField(options, "exclusivity")
    ? (newPop.exclusivity ?? null)
    : (newPop.exclusivity || existing.exclusivity);

  if (options.forceRefresh) {
    const updates = {
      pop_name: newPop.pop_name || existing.pop_name,
      character: newPop.character || existing.character,
      franchise: newPop.franchise || existing.franchise,
      number: newPop.number || existing.number,
      variant,
      exclusivity,
      pop_type: newPop.pop_type || existing.pop_type,
      pop_style: newPop.pop_style || existing.pop_style,
      set_name: newPop.set_name || existing.set_name,
      set_total: existing.set_total ?? newPop.set_total,
      vault_status: newPop.vault_status || existing.vault_status,
      limited_edition: newPop.limited_edition || existing.limited_edition,
      limited_count: newPop.limited_count ?? existing.limited_count,
      edition_notes: newPop.edition_notes || existing.edition_notes,
      estimated_value: options.resolvedRefreshEstimatedValue,
      description: newPop.description || existing.description,
      display_description: newPop.display_description || existing.display_description,
      description_source: newPop.description_source || existing.description_source,
      description_source_url: newPop.description_source_url || existing.description_source_url,
      description_quality: newPop.description_quality || existing.description_quality,
      description_last_checked: newPop.description_last_checked || existing.description_last_checked,
      description_review_notes: newPop.description_review_notes || existing.description_review_notes,
      api_source: newPop.api_source || existing.api_source,
      api_last_updated: newPop.api_last_updated,
      raw_api_json: newPop.raw_api_json ?? existing.raw_api_json,
      image_url: options.imageBlocked ? null : existing.image_url,
      release_date: newPop.release_date || existing.release_date,
      raw_title: newPop.raw_title || existing.raw_title,
      clean_title: newPop.clean_title || existing.clean_title,
      parse_confidence: Math.max(Number(newPop.parse_confidence ?? 0), Number(existing.parse_confidence ?? 0)),
      parse_reason_codes: newPop.parse_reason_codes ?? existing.parse_reason_codes,
      needs_review: mergeNeedsReview(existing.needs_review, newPop.needs_review),
    };
    return {
      ...updates,
      parse_reason_codes: pruneResolvedParseReasonCodes(updates.parse_reason_codes, updates),
    };
  }

  const updates = {
    ...newPop,
    pop_name: newPop.pop_name || existing.pop_name,
    character: newPop.character || existing.character,
    franchise: newPop.franchise || existing.franchise,
    number: newPop.number || existing.number,
    variant,
    exclusivity,
    pop_type: newPop.pop_type || existing.pop_type,
    pop_style: newPop.pop_style || existing.pop_style,
    set_name: newPop.set_name || existing.set_name,
    set_total: existing.set_total ?? newPop.set_total,
    image_url: options.imageBlocked ? null : newPop.image_url || existing.image_url,
    vault_status: newPop.vault_status || existing.vault_status,
    release_date: newPop.release_date || existing.release_date,
    limited_edition: newPop.limited_edition || existing.limited_edition,
    limited_count: newPop.limited_count ?? existing.limited_count,
    edition_notes: newPop.edition_notes || existing.edition_notes,
    estimated_value: newPop.estimated_value ?? existing.estimated_value,
    description: newPop.description || existing.description,
    display_description: newPop.display_description || existing.display_description,
    description_source: newPop.description_source || existing.description_source,
    description_source_url: newPop.description_source_url || existing.description_source_url,
    description_quality: newPop.description_quality || existing.description_quality,
    description_last_checked: newPop.description_last_checked || existing.description_last_checked,
    description_review_notes: newPop.description_review_notes || existing.description_review_notes,
    raw_title: newPop.raw_title || existing.raw_title,
    clean_title: newPop.clean_title || existing.clean_title,
    parse_confidence: Math.max(Number(newPop.parse_confidence ?? 0), Number(existing.parse_confidence ?? 0)),
    parse_reason_codes: newPop.parse_reason_codes ?? existing.parse_reason_codes,
    needs_review: mergeNeedsReview(existing.needs_review, newPop.needs_review),
  };
  return {
    ...updates,
    parse_reason_codes: pruneResolvedParseReasonCodes(updates.parse_reason_codes, updates),
  };
}
